# C++ Qt5 Program to Convert Excel Files to CSV

Here's a complete C++ program using Qt5 that:
1. Opens a file dialog to select a directory
2. Creates a new "CSV_Output" folder in that directory
3. Converts all Excel files (.xlsx, .xls) in the directory to CSV format

```cpp
#include <QApplication>
#include <QFileDialog>
#include <QDir>
#include <QMessageBox>
#include <QDebug>
#include <QAxObject>
#include <QProgressDialog>

class ExcelToCsvConverter : public QObject {
    Q_OBJECT

public:
    ExcelToCsvConverter(QObject *parent = nullptr) : QObject(parent) {}

    bool convertDirectory(const QString &dirPath) {
        QDir directory(dirPath);
        if (!directory.exists()) {
            QMessageBox::critical(nullptr, "Error", "Selected directory does not exist!");
            return false;
        }

        // Create output directory
        QString outputDirPath = dirPath + "/CSV_Output";
        QDir outputDir(outputDirPath);
        if (!outputDir.exists()) {
            if (!outputDir.mkpath(".")) {
                QMessageBox::critical(nullptr, "Error", "Failed to create output directory!");
                return false;
            }
        }

        // Get all Excel files in directory
        QStringList filters;
        filters << "*.xlsx" << "*.xls";
        QStringList excelFiles = directory.entryList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(nullptr, "Info", "No Excel files found in the selected directory.");
            return true;
        }

        // Initialize Excel application
        QAxObject *excel = new QAxObject("Excel.Application", this);
        if (!excel || excel->isNull()) {
            QMessageBox::critical(nullptr, "Error", "Failed to initialize Excel application. Make sure Microsoft Excel is installed.");
            return false;
        }

        // Don't show Excel to the user
        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QProgressDialog progress("Converting Excel files to CSV...", "Cancel", 0, excelFiles.size());
        progress.setWindowModality(Qt::WindowModal);
        progress.setMinimumDuration(0);

        int successCount = 0;

        for (int i = 0; i < excelFiles.size(); ++i) {
            progress.setValue(i);
            if (progress.wasCanceled()) {
                break;
            }

            QString excelFilePath = dirPath + "/" + excelFiles[i];
            QString csvFilePath = outputDirPath + "/" + QFileInfo(excelFiles[i]).baseName() + ".csv";

            if (convertFile(excel, excelFilePath, csvFilePath)) {
                successCount++;
            }

            progress.setLabelText(QString("Converting file %1 of %2").arg(i + 1).arg(excelFiles.size()));
        }

        progress.setValue(excelFiles.size());

        // Clean up Excel
        excel->dynamicCall("Quit()");
        delete excel;

        QMessageBox::information(nullptr, "Conversion Complete",
                                QString("Successfully converted %1 of %2 Excel files to CSV.")
                                .arg(successCount).arg(excelFiles.size()));

        return true;
    }

private:
    bool convertFile(QAxObject *excel, const QString &excelFilePath, const QString &csvFilePath) {
        QAxObject *workbooks = excel->querySubObject("Workbooks");
        if (!workbooks) {
            qWarning() << "Failed to get Workbooks object";
            return false;
        }

        QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelFilePath);
        if (!workbook) {
            qWarning() << "Failed to open workbook:" << excelFilePath;
            return false;
        }

        // Get the first worksheet
        QAxObject *worksheets = workbook->querySubObject("Worksheets");
        if (!worksheets) {
            qWarning() << "Failed to get Worksheets object";
            workbook->dynamicCall("Close()");
            return false;
        }

        QAxObject *worksheet = worksheets->querySubObject("Item(int)", 1);
        if (!worksheet) {
            qWarning() << "Failed to get Worksheet object";
            workbook->dynamicCall("Close()");
            return false;
        }

        // Save as CSV
        bool success = worksheet->dynamicCall("SaveAs(const QString&, int)",
                                             csvFilePath, 6); // 6 = xlCSV format

        workbook->dynamicCall("Close()");

        if (!success) {
            qWarning() << "Failed to save as CSV:" << csvFilePath;
            return false;
        }

        return true;
    }
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    // Set up the main window (though we won't show it)
    QWidget window;
    window.setWindowTitle("Excel to CSV Converter");

    // Create converter
    ExcelToCsvConverter converter;

    // Show directory selection dialog
    QString dirPath = QFileDialog::getExistingDirectory(nullptr,
                                                       "Select Directory with Excel Files",
                                                       QDir::homePath(),
                                                       QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

    if (!dirPath.isEmpty()) {
        converter.convertDirectory(dirPath);
    }

    return app.exec();
}

#include "main.moc"
```

## How to Compile and Run

1. Make sure you have Qt5 and Microsoft Excel installed on your system.
2. Create a project file (e.g., `excel_to_csv.pro`):

```qmake
QT += axcontainer widgets
TARGET = ExcelToCsvConverter
SOURCES = main.cpp
```

3. Compile with:
```bash
qmake excel_to_csv.pro
make
```

4. Run the executable.

## Notes

1. This code requires Microsoft Excel to be installed on the system as it uses Excel's COM interface.
2. The program will create a "CSV_Output" folder in the selected directory.
3. It only converts the first worksheet of each Excel file to CSV.
4. The progress dialog shows the conversion progress and allows cancellation.
5. Error messages will be displayed if something goes wrong.

## Alternative Approach

If you don't want to depend on Excel being installed, you could use a library like:
- [QtXlsx](https://github.com/dbzhang800/QtXlsxWriter) (for writing)
- [libxlsxwriter](https://libxlsxwriter.github.io/) (for writing)
- [libxls](https://github.com/libxls/libxls) (for reading older .xls files)

However, these libraries typically don't support all Excel features and might have limitations compared to using Excel's native COM interface.

